UPDATE `locales_page_text` SET `text_loc4` = '<HTML>
<身体>
<BR/>
<BR/>
<H1align="center">荆棘谷的青山</H1>
<BR/>
<H3align="center">赫米特·奈辛瓦里</H3>
</正文>
</HTML>' WHERE `entry` = 2945 AND `text_loc4` = '<HTML><BODY><H1 align="center">荆棘谷的青山';
UPDATE `locales_page_text` SET `text_loc4` = '在接下来的几年里，暴风城背叛了石匠公会后，埃尔加丁爵士对贵族在王国中的角色感到不满。 他不想再维护他父亲的血统为他在贵族院中赢得的地位。

但我离题了。 这个故事的目的不是作为政治论文或传记。 这是我在荆棘谷的绿色山丘中狩猎大型动物的经历的记述……' WHERE `entry` = 2949 AND `text_loc4` = '接下来的几年，在暴风城背叛了石匠公会後，艾尔加丁爵士开始厌恶他的贵族身份。他显然对继承他父亲的高贵血统，而获得崇高地位的这件事感到厌恶。$B$B不过我离题了。这个故事的主题不是政治文章或者人物传记，而是要叙述我在荆棘谷的青山中猎捕的经历。';
UPDATE `locales_page_text` SET `text_loc4` = '在上面的岩石悬崖上，在夕阳的映衬下，我可以辨认出我所见过的最大的猛禽。 我用步枪笨拙地开了一枪，但那只猫坚守阵地。 他再次咆哮，这一次比第一次更响亮，然后消失了。

我们收拾好行李，庄严地返回营地。' WHERE `entry` = 2956 AND `text_loc4` = '在遍布岩石的悬崖上，一只迄今为止我见过的最巨大的猎豹在晚霞的映衬中冒了出来。我笨拙地开了枪，但是那只豹丝毫未动。它又咆哮了一声，比第一次的声音更大，然後就消失了。$B$B我们把东西收好，然後神色黯然地返回了营地。';
UPDATE `locales_page_text` SET `text_loc4` = '几周过去了，我们的豹皮和虎皮库存不断增加。 我决定是时候将探险队的注意力转移到新的挑战上：猛龙队。

人类虽然很感激巴尼尔和我提供的训练，但决定不再使用枪支狩猎。 阿杰克对上弦的弓更加得心应手，而埃尔加丁爵士每次离开营地时都会带着他坚固的十字弓。' WHERE `entry` = 2964 AND `text_loc4` = '过了几个星期，我们的豹皮和虎皮储备已经相当充足了。於是我决定将探险队的注意力转向一个新的挑战:迅猛龙。$B$B队伍中的两个人类虽然十分感激我和巴尼尔对他们进行的训练，不过他们还是决定不使用我们提供的火枪去打猎。艾耶克更喜欢她那调校完美的强弓，而艾尔加丁爵士离开营地的时候总是拿着他的弩。';
UPDATE `locales_page_text` SET `text_loc4` = '我曾在战场上站在一座高耸的地狱火面前，燃烧军团的军队从四面八方推进。 一群不守规矩的巨魔看起来就像丹莫罗山上的长耳大野兔一样无害。

我们顺利通过了特卡什遗址，这让巴尼尔松了口气。 队伍继续向西行进，向大海前进，绕过南边的祖尔昆达废墟。 当我们登上公海悬崖时，我们发现了我们的第一架猛禽。' WHERE `entry` = 2966 AND `text_loc4` = '我曾经在战场上面对过巨大的炼狱火，还有从四面八方冲过来的燃烧军团。如今对我而言，一群蛮横的食人妖就跟丹莫洛的长耳大野兔一样不值一提。$B$B我们平静地穿过伽什废墟，巴尼尔总算是放下了他那颗惴惴不安的心。我们继续向西边的无尽之海前进，并绕了南边的祖昆达废墟。当我们攀上海边的悬崖之後，第一只迅猛龙出现在我们面前。';
UPDATE `locales_page_text` SET `text_loc4` = '这头野兽根本没有察觉到我们的存在。 事实上，他从探险队收到的唯一问候就是两眼之间的一颗子弹。

当阿杰克向我点头表示赞同时，埃尔加丁爵士发出了一声衷心的“欢呼”。 我翻遍了我的背包，寻找我的烟斗，希望能抽一口庆祝性的烟。 巴尼尔开始急忙爬上山坡去取回猛禽的尸体。 我盯着那头倒下的野兽，带着每次大杀戮所伴随的满足感。' WHERE `entry` = 2967 AND `text_loc4` = '这头野兽压根没有发现我们的存在，事实上，它从我们这儿收到的第一个问候就是射入它双眼间的子弹。$B$B艾尔加丁爵士大声欢呼，艾耶克则赞许地向我点了点头。我从包里拿出烟斗，想好好庆祝一番。巴尼尔奔上山坡去拖迅猛龙的屍体。我看着被击倒的野兽，心里就像以前每一次杀死猎物时那样充满着兴奋和满足。';
UPDATE `locales_page_text` SET `text_loc4` = '但我无法长时间沉浸在杀戮的荣耀之中。 因为当我把目光转向地平线时，几个剪影出现在山顶上，就在可怜的巴尼尔上方。

*逃跑，巴尼尔！*我喊道。 阿耶克、埃尔加丁爵士和我向巴尼尔上方和追击的猛禽队发射了一连串的子弹、箭和弩箭。 我们中的一个人在一片混乱中击杀了敌人。' WHERE `entry` = 2968 AND `text_loc4` = '但是我还没有时间体会这次猎杀的愉悦，就赫然发现山顶上出现了几个影子─就在可怜的巴尼尔的正上方。$B$B「快跑，巴尼尔!」我大叫道。艾耶克、艾尔加丁和我立刻向追逐巴尼尔的迅猛龙射击，一时间子弹和箭矢乱飞，混乱之中，我们当中的某人还射杀了一只迅猛龙。';
UPDATE `locales_page_text` SET `text_loc4` = '我们匆忙瞄准的射击足以让巴尼尔逃脱。 巴尼尔嚷嚷着下山，重新加入了队伍。 我们急忙跑进丛林。 一群凶猛的鞭尾猛禽跟踪我们的一举一动。

猎人现在成了猎物。' WHERE `entry` = 2969 AND `text_loc4` = '我们匆忙射出的子弹为巴尼尔赢得了足够的逃跑时间。他大声叫嚷着跑下山丘，重新回到队伍之中。我们急忙离开了丛林，因为有一群凶残的鞭尾迅猛龙正在追寻着我们的足迹。$B$B现在攻守易位，猎手变成了猎物。';
