DELETE FROM `locales_page_text` WHERE `entry` = 37 AND `text_loc4` = '尊敬的所罗门镇长:$B$B我和您一样为死去的人而哀悼。我会确保让国王陛下了解到目前的状况，同时我也衷心希望能为湖畔镇增派援军。不过奇怪的是，陛下最近没有什麽举动，这件事我只能私下对您说说。$B$B请多加保重，$B$B马库斯·乔纳森将军$B暴风王国';
DELETE FROM `locales_page_text` WHERE `entry` = 40 AND `text_loc4` = '他们有一个庞大的地下网路。斯托曼，这个网路比你所知道的更为庞大。从藏宝海湾到暴风要塞都有他们的势力。也许你是个勇敢的圣骑士，不过如果你以为，凭你的一己之力就能阻止他们，那你就太傻了。他们正在研究一种大规模杀伤性武器。总之，那些石工的看家本领就是如何制造大家伙。你不会以为他们的兴趣只是南瓜田和葡萄园吧?我已经报答了你为我提供的帮助。现在，离我远点吧!$B$B─W';
DELETE FROM `locales_page_text` WHERE `entry` = 57 AND `text_loc4` = '[契约的背后潦草地写着以下文字]$B$B 我们从法布隆那里弄到了他的契约，如果你想为自己伪造一份契约的话也很容易，法布隆不会给我们带来任何麻烦的。我上一次看到他们的时候，他们一家人正在离开西部荒野，不过因为四轮货车坏掉而不得不停了下来。';
DELETE FROM `locales_page_text` WHERE `entry` = 61 AND `text_loc4` = '当我们的同胞永远离去$B走进未知的土地$B在山谷的深处$B灵魂与精神变得坚强。$B当我们的同胞永远离去$B来到山上的圣殿$B我们将保卫他们永恒的精神$B将它镶入神圣的蓝水晶。$B当我们的同胞永远离去$B月亮照耀着山谷。';
DELETE FROM `locales_page_text` WHERE `entry` = 77 AND `text_loc4` = '第一天$B$B今天我和学徒来到了寒脊山谷，平安无事地穿过了洞穴之後，我们在食人妖巢穴外的安全地带紮了营。$B$B第二天$B$B该死的狼嚎声让我整晚都没睡着。$B$B明天我就要去弄一套狼皮做的衣服。$B$B今天那个年轻的学徒，相当英勇地与石齶怪战斗，也成功地战胜了那些丑陋的东西，不过他的胳膊受伤了，得好好休养一下。看来这阵子得由我来打理了。';
DELETE FROM `locales_page_text` WHERE `entry` = 97 AND `text_loc4` = '荆棘谷的青山$B$B 第一天和我们预想中的完全一样。我们大部分时间都忙于为创建营地做一些必要的准备。我在一条淡水河的入口处找到了理想的驻扎点。根据旁边被废弃的古老码头判断，这个地方曾经有人住过，不过只有时间才能说明这里究竟住过些什么人。';
DELETE FROM `locales_page_text` WHERE `entry` = 99 AND `text_loc4` = '接下来的几年，在暴风城背叛了石匠公会後，艾尔加丁爵士开始厌恶他的贵族身份。他不愿因继承了他父亲的高贵血统而在贵族中获得崇高的地位。不过我离题了。这个故事的主题不是政治文章或者人物传记，而是要叙述我在荆棘谷的青山中猎捕的经历。';
DELETE FROM `locales_page_text` WHERE `entry` = 101 AND `text_loc4` = '正在我准备问艾耶克为什么一整天都无精打采的时候，她突然从箭囊中抽出一支箭，向可怜的巴尼尔射去─当然她的目标并非巴尼尔。瞠目结舌的巴尼尔向后退了几步，看着自己身后的一只巨大的鳄鱼浮出水面，艾耶克的箭正好射在了它的两只眼睛的中间。';
DELETE FROM `locales_page_text` WHERE `entry` = 103 AND `text_loc4` = '艾尔加丁爵士似乎被绊了一下，将手重重地拍在巴尼尔的肩膀上。我和艾耶克瞥了一眼，以为他会责备粗心大意的巴尼尔。然而艾尔加丁爵士却摆了摆头，示意我们观察旁边的一棵倒下的大树。那里正有一双炯炯有神的黑眼睛瞪着我们，眼睛下面还有一口如剃刀般锋利的牙齿。';
DELETE FROM `locales_page_text` WHERE `entry` = 107 AND `text_loc4` = '在遍布岩石的悬崖上，一只迄今为止我见过的最巨大的猎豹在晚霞的映衬中冒了出来。我笨拙地开了枪，但是那只豹丝毫未动。它又咆哮了一声，比第一次的声音更大，然後就消失了。$B$B我们把东西收好，然後神色黯然地返回了营地。';
DELETE FROM `locales_page_text` WHERE `entry` = 109 AND `text_loc4` = '这一天，我们沿着一些新的黑豹足迹向南进发。很快我们就来到了一座架着巨大索桥的峡谷。看到这个工程奇蹟的时候，我忍不住想起了布莱恩对这一带的描写。我们常常认为食人妖是原始而无知的族类，然而当我认识到这座索桥所体现的精湛技术时，我开始认为食人妖的建造技术已经达到令人难以想像的地步。';
DELETE FROM `locales_page_text` WHERE `entry` = 111 AND `text_loc4` = '艾耶克和艾尔加丁爵士悄无声息地用枪瞄准着正在晃动的树丛。正午的强烈阳光照在我们身上，当艾尔加丁爵士终於扣动扳机的时候，他的额头流下了一丝汗水。一声枪响过後，浓密的树叶被打得乱飞，一只非常漂亮的大黑豹向离弦的箭一般冲向了平原。';
DELETE FROM `locales_page_text` WHERE `entry` = 113 AND `text_loc4` = '他的枪重重地击在他的肩膀上，枪管歪向一边，正好落在艾耶克的枪下面。艾耶克瞄准树冠适时地扣动了扳机，一声清晰的枪响过後，树冠上的一群鸟尖叫着四处飞散，树上冒出了一阵烟，我们惊异地看到一根巨大的树枝掉落下来，正好砸中了疾驰的黑豹。';
DELETE FROM `locales_page_text` WHERE `entry` = 117 AND `text_loc4` = '我曾经在战场上面对过巨大的炼狱火，还有从四面八方冲过来的燃烧军团。如今对我而言，一群蛮横的食人妖就跟丹莫洛的长耳大野兔一样不值一提。$B$B我们平静地穿过伽什废墟，巴尼尔总算是放下了他那颗惴惴不安的心。我们继续向西边的无尽之海前进，并绕了南边的祖昆达废墟。当我们攀上海边的悬崖之後，第一只迅猛龙出现在我们面前。';
DELETE FROM `locales_page_text` WHERE `entry` = 152 AND `text_loc4` = '艾耶克和艾尔加丁爵士拿起他们的武器，守在我的两侧，我们的背後就是大海。巴尼尔沮丧地叹了一口长气，然後拿起了他的斧头。迅猛龙在慢慢地逼近，它们高傲地注视着我们，因为它们知道我们已经无路可逃了。';
DELETE FROM `locales_page_text` WHERE `entry` = 204 AND `text_loc4` = '我无法描述接下来所发生的事情。它深深地刻在我的脑海里，但是我脆弱的灵魂无法把它写下来，那是短暂而又无比恐怖的时刻。$B$B我只能写下事情的结局:斯温的一家都被杀害了。没过多久，斯温回来了，他看到了这一片死亡的惨景，悲痛欲绝，这使我不敢现身。我不敢让他找到我，於是我就从农场里逃走了。我也不知道斯温现在在哪里，但是我希望有一天他能平静下来。';
DELETE FROM `locales_page_text` WHERE `entry` = 217 AND `text_loc4` = '亲爱的伊维特:$B$B我将委托我们这里最迅捷的信差将这封信交给你，希望他能设法穿越我们之间茂密的森林。我希望你能读到这个，因为这将是你最後一次收到我的消息了。$B$B在这黑暗的日子里，只有当我知道了你不会再经受我所经受的厄运，我才能感到些许的安慰。';
DELETE FROM `locales_page_text` WHERE `entry` = 228 AND `text_loc4` = '应该可以收集到布瑞尔地区的不死生物活动情报。$B$B瓦松队长，北部哨塔一带的不死生物活动日益增加，必须快速果断地消灭这种活动。$B$B麦罗斯队长，瘟疫之地边界地区的不死生物正在不断集结。增援部队将在接下来的几周内到达你的辖区。$B$B沐浴在圣光的荣耀之下';
DELETE FROM `locales_page_text` WHERE `entry` = 247 AND `text_loc4` = '您好，主人。$B$B 请原谅我用这种方式给您写信。奥特兰克的暗影法师正在忙于他们的计划，我不得不使用外面的——从我们新的“盟友”中招募的——信差给您送信。但我用了我们最深奥的口令来撰写这封信的具体内容，所以由这些乡巴佬送信是非常安全的。';
DELETE FROM `locales_page_text` WHERE `entry` = 305 AND `text_loc4` = '血帆命令$B$B亲爱的水手们，请仔细看好这篇命令中的内容，因为我们在藏宝海湾发财的机会只有一次。$B$B我已经派邓肯守在北边，并告诉他等待行动的信号。$B$B达姆希的好运号将停靠在南边的海角旁等待补给命令。小个子的斯蒂沃特船长会让他的船员做好运送战利品的准备。我相信布鲁图斯那个蠢货会是我们最大的麻烦。';
DELETE FROM `locales_page_text` WHERE `entry` = 339 AND `text_loc4` = '同时，我还派出了阿维罗德上尉，在卡林多大陆执行侦察任务。他的部队完成任务之後，会与我们在提拉加德城堡的部队会合。$B$B阿维罗德上尉的任务可能需要很长时间，因为这片新大陆幅员辽阔、充满危机。如果我或者本尼迪克遭遇不幸的话，阿维罗德将接手城堡的指挥权。$B$B我们会发动一轮接一轮的攻击，直到占领这座要塞!$B$B- 普劳德摩尔上将';
DELETE FROM `locales_page_text` WHERE `entry` = 363 AND `text_loc4` = '德尔葛兰大人:$B$B事情正像您所担忧的那样。您关於奥萨拉克斯之塔的猜测是正确的。有一群邪恶的信徒聚集在奥萨拉克斯之塔一带，他们当中有许多术士，甚至还有一个凶残的萨特。我不清楚是何种邪恶的力量将他们聚集在一起，但是我对此感到十分忧虑。$B$B他们自称是暗滩教派的信徒。$B$B请原谅我这封信写得很简短，但是危险正潜藏在森林中，我只能简单地描述一下这里的情景。';
DELETE FROM `locales_page_text` WHERE `entry` = 393 AND `text_loc4` = '於是他到处游荡、寻找。而他还是没有找回那只手臂。於是他一边走一边咒骂怒号着。$B$B但是格里雷克已经很久没有听从神灵的教诲，他们因此而愤怒，不再理会他的咒骂。$B$B格里雷克的命运就是这样，命运让他不断游荡，让他缺少一只手臂。';
DELETE FROM `locales_page_text` WHERE `entry` = 423 AND `text_loc4` = '风险投资公司的函件在矿坑的外面……可能在底层的什麽木箱里。$B$B祝你好运，记住……$B$B蓝色炸药:伐木场$B红色炸药:矿坑$B$B哦，完成任务之後别忘了把信也毁了。嗯，也许我该想个办法让这些东西在被人读过之後就自我销毁，这个主意不错……';
DELETE FROM `locales_page_text` WHERE `entry` = 466 AND `text_loc4` = '恭喜您!$B$B 您已经成为了这只地鼠的新主人!虽然它看起来很害羞，但我们确信您会发现它非常可爱，而且具有出色的能力。$B$B 在接下来的几页中，您将找到关于地鼠的详细信息：$B$B 再一次对您表示祝贺。您是绝对不会对它失望的。$B$B - 玛维格・铜拴$B 地鼠有限公司';
DELETE FROM `locales_page_text` WHERE `entry` = 506 AND `text_loc4` = '恭喜您!$B$B您已经成为了这只地鼠的新主人!虽然它看起来很害羞，但我们确信您会发现它非常可爱，而且具有出色的能力。$B$B在接下来的几页中，您将找到关於地鼠的详细资讯:$B$B1. 喂食和照料须知$B2. 奇怪(而且可爱)的习惯$B3. 地鼠指挥棒(tm)的使用 $B$B再一次对您表示祝贺。您是绝对不会对它失望的。$B$B- 玛维格·铜拴$B地鼠有限公司';
DELETE FROM `locales_page_text` WHERE `entry` = 606 AND `text_loc4` = '「最好在离其目的地不远处下手，据说我们的「盟友」也埋伏在那一带。我真是不明白，我们为什麽要和那种生物结成同盟，但我也没有什麽办法，我们是迫不得已。不过算了，这也没什麽。只要我们能牢牢揪着目标，就一定可以从暴风城那里，拿回当初他们从我们手中偷走的东西!」';
DELETE FROM `locales_page_text` WHERE `entry` = 626 AND `text_loc4` = '长须先生：$B$B 正如阁下所知，我们雷矛系列有着全大陆最挑剔的眼光和品味，您所制作的盾牌质量之高也是令我们非常欣赏的。$B$B 因此，我非常希望能得到一面由您亲手打造的盾牌。以下是我对盾牌的一些个人要求：';
DELETE FROM `locales_page_text` WHERE `entry` = 689 AND `text_loc4` = '我们会以一如往常的方式支付。此外，请给这位信差支付一份标准的报酬，您可以把它算进盾牌的价格中。$B$B非常感谢!$B您真诚的格林戈·雷矛';
DELETE FROM `locales_page_text` WHERE `entry` = 710 AND `text_loc4` = '我真希望，再没有其他达拉然巫师召唤狼人了─即使是出於良好的目的。只要不再签订更多的契约，就不会有更多的秘密被泄露出去，这些野兽不会为我们带来任何好处的。$B$B它们最好永远留在它们的世界里。如果它们来到我们的世界，那我们无疑将面临毁灭的劫难……';
DELETE FROM `locales_page_text` WHERE `entry` = 712 AND `text_loc4` = '身为卡加斯派出的斥候，我对周围环境的描述如下：$B$B - 红色的岩石丘陵与干燥的平原，只有极少数生物才能在此生存。$B - 阳光炽烈，强风。$B - 没有湖泊和溪流，也没有任何池塘。想要找水的话，就必须挖出泥泞的深井，或者从仙人掌与其它针刺类植物中榨水。$B$B 简而言之：燥热，难以生存。';
DELETE FROM `locales_page_text` WHERE `entry` = 713 AND `text_loc4` = '荒芜之地中满是我们的敌人。巨魔会从沙中咆哮着突然钻出，伏击任何缺乏警惕的冒险者。黑铁矮人则在卡加斯的东部创建了一处基地，并和他们那些浅色皮肤的表亲们在洛克莫丹北部地方交战。某种野蛮且原始的名为穴居人的种族疯狂地占据着这里的每一片土地，并寸步不让地保护着他们的领地。$B$B 那么荒芜之地东部的莱瑟罗峡谷呢?它彻底被龙占据了。我们不知道那里的龙有多少，也不知道他们有多强大，因为派去那边侦查的斥候没有一个能活着回来的。';
DELETE FROM `locales_page_text` WHERE `entry` = 714 AND `text_loc4` = '不用说就知道，我们卡加斯卫戍部队对能够被部署在这里感到非常高兴。我们已经在这里坚强地扎下了根，因为只要我们略微示弱，就会死在这里。$B$B 在这里也没有别的办法可以生存下去了。$B$B 尼卡・血痕$B 斥候队长，卡加斯';
DELETE FROM `locales_page_text` WHERE `entry` = 730 AND `text_loc4` = '赫格拉姆，$B$B无论是谁提议，在荒芜之地的卡加斯建立一片基地，都将得到我的赞同。这个计画将使我们在那里拥有常备的驻军。那里的天气很糟，到处都是凶恶的野生动物与好战的土着，也没有什麽补给，惟有我们最好的战士与斥候，可以在那里立足。$B$B这计画很好。干得漂亮。';
DELETE FROM `locales_page_text` WHERE `entry` = 770 AND `text_loc4` = '你好啊，孩子。把这封信交给试炼谷里的弗朗恩，他就在大兽穴外面的帐篷下，负责将新兵训练成勇猛的战士。$B$B他需要像你这样机敏的战士，好让那些兽人明白，作战并不是只靠肌肉的。你非常聪明，行动也很迅速，但千万别自夸─兽人不喜欢被挑衅。他们是好盟友，希望他们能好好训练你。$B$B- 塔塞雷';
DELETE FROM `locales_page_text` WHERE `entry` = 790 AND `text_loc4` = '喂食和照料须知：$B$B 我们郑重承诺为您提供照料宠物所需的一切信息，让您从地鼠有限公司得到专业的服务!$B$B 为了达到这一目标，我们为牢固的地鼠笼设计了一些小孔，这让您的宠物可以在其中安逸地生活，而且不用受日晒雨淋之苦。$B$B 为了您的方便起见，每只笼子中都安装了一个喂食器，它带有诱人的蓝叶薯的味道（这是地鼠最喜欢的食物）!';
DELETE FROM `locales_page_text` WHERE `entry` = 810 AND `text_loc4` = '深渊公主阿库麦尔，一直以来都为上古诸神效力，她运用上古的智慧，为自己的洞穴祈祷。阿库麦尔是由古老的凡人带入黑涧深渊的，她是神的象徵。虽然她只拥有上古诸神很小一部分的力量，但是她已是如此的深不可测。$B$B她被信徒们崇拜着，畏惧着，热爱着。$B$B- 洛加利斯';
DELETE FROM `locales_page_text` WHERE `entry` = 830 AND `text_loc4` = '那些肮脏的石齶怪实在是太好唬弄了。它们对於我们的极端憎恨使得我们可以反过来利用它们……看来什麽样的同盟都可以形成啊，但是我们的那些同胞对於石齶怪来说确实有很大的威胁，至少现在是如此。$B$B战斗开始之後，他们双方的力量必然都会被削弱，然後我们就可以进军盔枕湖并等待下一步的指示了。$B$B铁炉堡终将是我们的。';
DELETE FROM `locales_page_text` WHERE `entry` = 870 AND `text_loc4` = '流放精华:$B$B提炼这种精华所必需的符咒可以从阿拉希高地的那些被放逐的元素生物身上找到。我们需要雷霆符咒、燃烧符咒和海浪符咒，每样八个，然后把它们放进我的容器中。$B$B有了符咒之后，我就可以合成流放精华了。';
DELETE FROM `locales_page_text` WHERE `entry` = 874 AND `text_loc4` = '精炼矿石:在塞尔萨玛有个叫白洛尔·石手的矮人铁匠，我曾经在他手下接受过训练。他能够制作一种非常特殊的合金，这种合金在你的武器中也是一个非常重要的组成部分。原本应该有一批这种合金被运到铁炉堡来的，但至今我还没有得到相关的消息。$B$B去找到他，帮我询问一下那批货的下落。如果他不在洛克莫丹的话，那我至少想要知道我的老师去哪里了。';
DELETE FROM `locales_page_text` WHERE `entry` = 890 AND `text_loc4` = '科尔宝石:从我所知道的一些传说来看，这种宝石是法师用来储存能量所用的，这可以极大地增强他们的力量。我曾经帮助过一个名叫桑迪斯·织风的夜精灵，他可以告诉你更多有关宝石的资讯，只要你和他提到我，他就一定会帮忙的。我相信这些宝石中一定蕴藏了可以帮你铸造武器的力量。$B$B我和桑迪斯上次见面的时候，他住在黑海岸的奥伯丁，那里是夜精灵的家园，周围都是被污染的森林。';
DELETE FROM `locales_page_text` WHERE `entry` = 910 AND `text_loc4` = '这张手卷上画满了旋转的记号和复杂的象形文字，这些奇怪的符号让你难以理解。';
DELETE FROM `locales_page_text` WHERE `entry` = 930 AND `text_loc4` = '一块碧玉。很多地方都有碧玉。它们很稀有，但是如果你去找某位铁匠或工程师谈谈的话，他们或许会有多余的碧玉可以卖给你。';
DELETE FROM `locales_page_text` WHERE `entry` = 950 AND `text_loc4` = '$N，你需要以下的东西来铸造你的护甲:$B$B石爪山狂风矿坑里的狗头人身上携带的烟雾铁锭。$B$B希尔斯布莱德矿坑里的蓝铜粉。$B$B铁锭则要从矿工们那里获取，当然如果你自己也会采矿的话就更好了。$B$B至於燃素，你必须从剃刀沼泽那边的一个名叫鲁古格的野猪人身上抢来。';
DELETE FROM `locales_page_text` WHERE `entry` = 970 AND `text_loc4` = '(这本又脏又皱的日志，只有一部份的内容可供辨识。)$B$B奥达曼，第三天$B$B我不敢相信自己居然那麽愚蠢。只有没经验的新手才会被暗炉矮人偷袭!我的伤口迟迟不能痊癒，显然我中了毒。我感到自己的体力越来越不行了。即便如此，我还得继续前行……$B$B……事情变得更糟了，侏儒为我制作的项链被打碎了!项链上最大的三颗宝石都不见了。我必须找到宝石，没有它们的话，项链根本没有用……';
DELETE FROM `locales_page_text` WHERE `entry` = 990 AND `text_loc4` = '奥达曼，第七天$B$B……这是我最後一次，弥补自己犯下的错误的机会了。我相信，红宝石就藏在矮人们不让穴居怪进入的地方。他们的战斗，无疑就是为了这块宝石和其他宝物。那些可恶的矮人，肯定把它藏在什麽地方了。不管这些了，我无论如何也得从这里走出去。或许直接向上挖条出路是最好的选择……';
DELETE FROM `locales_page_text` WHERE `entry` = 1010 AND `text_loc4` = '能得到这份证书的盗贼，也必将得到所有初级盗贼的尊敬和关注。';
DELETE FROM `locales_page_text` WHERE `entry` = 1030 AND `text_loc4` = '我发现了进入卡兹莫尔大厅的方法!$B$B从我的箱子中拿到尼基夫勳章。$B$B击败那个放着地图的房间前面小房间里的穴居怪鲁维罗什，然後拿到索尔之杖。$B$B将这两者合成史前法杖。$B$B在那个布置着地图的房间里使用法杖，就可以打开卡兹莫尔大厅的门。$B$B只要按照以上步骤来做，你就可以进入那个房间了!$B- 巴尔洛戈';
DELETE FROM `locales_page_text` WHERE `entry` = 1050 AND `text_loc4` = '<HTML><BODY><BR/><BR/><P>纪念我亲爱的良师，霍拉迪·蒙特高莫，医学博士。一位医者，老师，朋友。</P><BR/><H1 align="center">50 BTFT - 25 ATFT</H1><BR/><P>"世界充满了病痛与疲惫。这是我们的工作，身为医者，同时，也是男人与女人的良药，净化他们的苦痛。" </P><BR/><P>- H.M.M., M.D., PhD, JD, 农夫大师，非凡的舞蹈家，动物的朋友$';
DELETE FROM `locales_page_text` WHERE `entry` = 1130 AND `text_loc4` = '祖尔法拉克之槌    想要创造祖尔法拉克之槌，你首先要从祖尔祭坛的巨魔守护者手中夺取神圣之槌。    将神圣之槌拿到巨魔城市辛萨罗顶部的祭坛上。    在祭坛上使用神圣之槌，将祭坛的力量灌入其中，这样就能创造出祖尔法拉克之槌了。';
DELETE FROM `locales_page_text` WHERE `entry` = 1150 AND `text_loc4` = '超级临界三倍编码资料卡$B$B01010100 01101000 01110010 01100001 01101100 01101100 00100000 01100001 01101110 01100100 00100000 01001010 01100001 01101001 01101110 01100001 00100000 01110011 01101001 01110100 01110100 01101001 01101110 01100111 00100000 01101001 01101110 00100000 01100001 00100000 01110100 01110010 01100101 01100101 00101100 00100000 01001011 00101101 01001001 00101101 01010011 00101101 01010011 00101101 01001001 00101101 01001110 00101101 01000111';
DELETE FROM `locales_page_text` WHERE `entry` = 1170 AND `text_loc4` = '克格尔:$B$B我一直都在急切盼望着得到你的最新发明，我已经等不及要用它来记录我的研究成果了!$B$B请将你的发明交给我的信差。$B$B此致$B$B达蕾恩·轻风';
DELETE FROM `locales_page_text` WHERE `entry` = 1210 AND `text_loc4` = '以下资料的安全等级非常高，必须重新发明一种数位记录方式才能对其进行安全等级定义!$B$B01001101 01100101 01110011 01110011 01100001 01100111 01100101 00100000 01110100 01101111 00100000 01000011 01100001 01110011 01110100 01110000 01101001 01110000 01100101 00111010 00100000 01111001 01101111 01110101 01110010 00100000 01101100 01100001 01110101 01101110 01100100 01111001 00100111 01110011 00100000 01110010 01100101 01100001 01100100 01111001 00100000 01100110 01101111 01110010 00100000 01110000 01101001 01100011 01101011 01110101 01110000 00101110';
DELETE FROM `locales_page_text` WHERE `entry` = 1310 AND `text_loc4` = '更多引用!$B$B「完成某件超强的发明并亲身感受它的力量，你知道这样的感觉是多麽美妙吗?侏儒可不知道。」$B-- 尼克斯·斯普克斯宾，加基森高级工程师$B$B「工程学就是让幻想变得更加奇妙的东西!」$B-- 洛维斯，侏儒发明家';
DELETE FROM `locales_page_text` WHERE `entry` = 1330 AND `text_loc4` = '任何一个有智慧的生物找到这张便笺的时候，他们都一定会自问道:「为什麽他们会去招惹具有暴力倾向的30尺高的巨人呢?」$B$B-- 穆克';
DELETE FROM `locales_page_text` WHERE `entry` = 1430 AND `text_loc4` = '尼尔斯修士:$B$B我的葡萄得救了!$N，也就是这封信的携带者，勇敢地闯入我那满是盗贼的园子，然後带着我的葡萄杀了出来。虽然迪菲亚兄弟会的人依然在河岸上巡逻，但是我所有的收成几乎全都保住了。$B$B你可以在你的商店中再次供应葡萄了。$B$B愿圣光保佑我们，$B- 米莉·奥斯沃斯';
DELETE FROM `locales_page_text` WHERE `entry` = 1470 AND `text_loc4` = '佩沃尔·铁足$B$B黑暗守卫者佩沃尔是我们最为尊重的侍徒。他携带黑暗之钥的时间远远超过其他黑暗守卫者，这使他付出了惊人的代价。$B$B他的牺牲让我们感到惋惜，对他的怀念会一直留在我们心中……自从黑暗占据了他。';
DELETE FROM `locales_page_text` WHERE `entry` = 1490 AND `text_loc4` = '所罗门镇长:$B$B这封命令的携带者已经被授予暴风城官方代表的资格。您可以让$G他:她;寻找黑龙军团和黑石兽人之间的联系。如果发现了此类证据，请让这个代表把证据带回暴风城，亲自交给我，届时我再酌情派遣部队来协助湖畔镇。$B$B此致，$B$B大领主伯瓦尔·弗塔根';
DELETE FROM `locales_page_text` WHERE `entry` = 1555 AND `text_loc4` = '古德斯迪尔的长剑 -$B$B最後，我要找回的是我最好的武器。我将这把神奇的长剑给了一名我非常尊重的战士。嗯，不过他被一个名叫加奎亚还是什麽的鱼人给袭击了。$B$B当他在悲伤沼泽那一带的海边旅行的时候遭到了那个家伙的攻击。他被打得落荒而逃，但是他没有把那把武器也一起带走，而是留给了那个鱼人。';
DELETE FROM `locales_page_text` WHERE `entry` = 1590 AND `text_loc4` = '帮我找到这些东西，然後带到加基森来─别忘了还有这个帐本，我会重赏你的。';
DELETE FROM `locales_page_text` WHERE `entry` = 1610 AND `text_loc4` = '这块铁砧是乔丹·斯迪威尔的财产 - 请不要使用!$B$B- 乔丹';
DELETE FROM `locales_page_text` WHERE `entry` = 1630 AND `text_loc4` = '<这个页面上写满了古代精灵文字。>$B$B这些书页中记述了在制作次级秘纹的过程中所发生的事件。$B$B愿我的敌人永远无法得到这些资料。$B$B愿我有生之年能够重见洁白的月光照耀奎尔萨拉斯。$B$B愿我能以凯尔萨斯之名奋战。$B$B愿我能为伊利丹的荣耀而战死。$B$B- 卡里尔·温萨鲁斯';
DELETE FROM `locales_page_text` WHERE `entry` = 1710 AND `text_loc4` = '你好，菲诺克!$B$B我在燃烧平原的研究进行得非常顺利。而且我欠了$N很多因为$G他的:她的;大力帮忙!以下是我继续研究所需要的物资:$B$B钢螺钉若干$B17号扳手一个$B12磅重的鸭毛$B一罐你制造的胶水$B$B非常感谢你，菲诺克，下次我们碰面的时候记得提醒我，不要把煤放在你的鞋子里!$B$B- 丁奇';
DELETE FROM `locales_page_text` WHERE `entry` = 1730 AND `text_loc4` = '给峭壁看守者长角的急件$B$B一大群半人马部队从伊索克营地出发并袭击了我们的补给营地。所有的守卫都已战死，所有的资源全部被劫掠一空。这是半人马发起的空前大胆的袭击，我担心将来还会有更多这样的袭击。';
DELETE FROM `locales_page_text` WHERE `entry` = 1750 AND `text_loc4` = '罗德隆的最後一位国王，泰瑞纳斯·米奈希尔二世在此长眠。$B$B他的一生做出了无数伟大的功绩，他的陨落令人扼腕叹息。$B$B         「愿这位父王宽恕其子嗣所做的一切。$B          愿血染的王冠永远被遗失和忘却。」';
DELETE FROM `locales_page_text` WHERE `entry` = 1827 AND `text_loc4` = '在确认永恒之井就是使恶魔进入这个世界的大门之後，玛法里恩坚持认为应该摧毁它。他的同伴们被他这个疯狂的想法吓呆了─永恒之井是他们长寿和力量的源泉。但是泰兰妲知道这是一个明智的抉择，於是她请求塞纳留斯和巨龙摧毁艾萨拉的神殿，并找到关闭永恒之井传送门的方法。';
DELETE FROM `locales_page_text` WHERE `entry` = 2063 AND `text_loc4` = '科尔苏加德领导的教徒急切地希望死去并为他们的主人服务，他们希望通过这种方式变成不死之身。随着瘟疫逐渐扩散，罗德隆北部出现了越来越多的殭屍，科尔苏加德管理着这支日益庞大的部队，并称他们为「天谴军团」─不久之後，它就会踏进罗德隆的大门，并把人类从这个世界上永远抹掉。';
DELETE FROM `locales_page_text` WHERE `entry` = 2130 AND `text_loc4` = '不幸地是，普劳德摩尔上将，在珍娜向他证明兽人已经不再是嗜血的怪物，并与他和解之前就战死了。出於珍娜对部落的忠诚情义，兽人们同意让她的部队安全地回到塞拉摩的家园。';
DELETE FROM `locales_page_text` WHERE `entry` = 2150 AND `text_loc4` = '向你致敬，战士。我不会再奉承你的力量与勇猛，这都是些陈年旧帐了。最近你杀了多少人?我猜没多少。你正在退步，你正在因为缺乏挑战而变得越来越弱。$B$B我可不能让一个战士就这麽变成废物，不会管别人是怎麽奉承你的，现在的事实就是:你需要接受训练，而我可以训练你。什麽时候你那榆木脑袋开窍了，就来找我吧，我在大兽穴外的帐篷下面。$B$B- 弗朗恩，战士训练师';
DELETE FROM `locales_page_text` WHERE `entry` = 2170 AND `text_loc4` = '多加尔·石眉$B血色十字军战士 $B红色洞穴的领主$B失踪於奥特兰克山脉';
DELETE FROM `locales_page_text` WHERE `entry` = 2190 AND `text_loc4` = '大约16,000年以前（远早于夜精灵愚蠢地召来燃烧军团的年代），食人妖主宰了卡利姆多大陆（那个时候只有一块大陆）的大部分区域。那个时候有两个食人妖帝国并存，即东南部森林中的古拉巴什帝国，以及中部的阿曼尼帝国。';
DELETE FROM `locales_page_text` WHERE `entry` = 2210 AND `text_loc4` = '内战後幸存的古拉巴什部族继续留在他们那已成为一片废墟的家园里，但是却走上了不同的路，劈颅部族、血顶部族和暗矛部族开始在荆棘谷争抢丛林领地。虽然他们最终达成了脆弱的和平，但仍有预言说哈卡将会在未来的某日在这个世界上重生，到那时，他将毁灭一切。';
DELETE FROM `locales_page_text` WHERE `entry` = 2250 AND `text_loc4` = 'A:$B$B我们从罗德隆派来的使者不久之後就会与你会面。一旦我们找到了进行会谈的合适地点，就会及时通知你。$B$B- G';
DELETE FROM `locales_page_text` WHERE `entry` = 2270 AND `text_loc4` = '攻击者……来自各个方向。$B$B木喉部族是邪恶的。敌人。$B$B必须保护冬泉部族。必须把入侵者赶出我们的土地。';
DELETE FROM `locales_page_text` WHERE `entry` = 2290 AND `text_loc4` = '纳塔卡，千针石林一切安好。半人马的麻烦还没有解决……它们有时候会发起攻击，但是当前还没有形成真正的威胁。然而，似乎有消息说半人马氏族正在集结。$B$B我们总是会认真考虑那些团结在一起的残忍氏族，比如半人马……我尝试着不去过多考虑这些问题，正如你所知的那样……没有什么东西可以消解它们心中那纯粹的憎恨……即使对于它们的同胞，那种憎恨也是非常强烈的。$B$B- 峭壁卫兵图林・长角';
DELETE FROM `locales_page_text` WHERE `entry` = 2390 AND `text_loc4` = '约瑟夫·雷德帕斯的命运$B$B约瑟夫·雷德帕斯在达隆郡一战中阵亡。他的灵魂已经堕落，被扭曲成了另一个模样，这个新的亡灵在罗德隆散播着更多的邪恶。$B$B在安多哈尔东部的盖罗恩农庄，堕落的雷德帕斯最终被联盟部队击败。他的盾牌依然留在那座被瘟疫感染的农庄谷仓旁边，天谴军团也不断向那个邪恶的地方聚集。';
DELETE FROM `locales_page_text` WHERE `entry` = 2410 AND `text_loc4` = '卡林·雷德帕斯的命运$B$B约瑟夫·雷德帕斯队长的兄弟，卡林·雷德帕斯在达隆郡的战斗中倒下了，他身负重伤，但是最终侥幸活了下来。$B$B在大战过後的几天，银色黎明组织发现了奄奄一息的卡林·雷德帕斯，他又渴又累，而且还发着烧，倒在了考林的十字路口附近。他们治疗了他的伤势，并把他带到了圣光之愿礼拜堂。$B$B由於对银色黎明的感激之情，卡林·雷德帕斯加入了银色黎明，并为了复仇而与天谴军团展开战斗。';
DELETE FROM `locales_page_text` WHERE `entry` = 2510 AND `text_loc4` = '瑞什:$B$B你的请假要求已经被批准了。我会派候补的牛头人战士去你执勤的哨所接班，这样你就可以回家和亲友团聚了。在一个星期的假期过後回来报到!$B$B- 马格兰';
DELETE FROM `locales_page_text` WHERE `entry` = 2530 AND `text_loc4` = '根据高级执行官哈德瑞克的命令，以下物品是维持瑟伯切尔库存的必需品:$B$B12把长剑$B9把匕首$B8面圆盾$B15把斧头$B1000支箭$B$B这些物品必须完全备齐，这是黑暗女王的直接命令，负责执行此命令者将受到她的关注，而任何违背这一命令的行为都将被认为是违背黑暗女王的意愿。';
DELETE FROM `locales_page_text` WHERE `entry` = 2550 AND `text_loc4` = '这三页的文件是空白的。';
DELETE FROM `locales_page_text` WHERE `entry` = 2570 AND `text_loc4` = '莱耶:$B$B我们受到了这位冒险者的帮助。现在我派$G他:她;到希利苏斯来帮助你。请好好利用$G他:她;的能力，解开那个地区的谜团。议会急切地等待着你的进度报告。$B$B愿塞纳留斯永远守护着你……$B- 拉比恩';
DELETE FROM `locales_page_text` WHERE `entry` = 2590 AND `text_loc4` = '现代习俗$B$B其他文明开始意识到冬幕节是一个欢庆的节日，虽然一些传统和传说中的并不完全一致。通常，人们可不会顾及太多关於节日本身的来历，他们所关心的只是在这个节日期间可以好好庆祝并交换礼物，这就是冬幕节现在的习俗。现在冬天爷爷的形象也广泛用在商业用途，而不是表现为一个超自然的泰坦巨人。';
DELETE FROM `locales_page_text` WHERE `entry` = 2594 AND `text_loc4` = '护符上面的五颗宝石都遗失了。如果能找回那些宝石，并把它们安到护符上，那麽它的力量将远远高於现在。我找到了那五块宝石，但是需要你这样强大的$C来拿回它们。杀了那个无名预言者无疑是极度罪恶的行为，但是我要让所有半人马从此打消对宝石的念头。';
DELETE FROM `locales_page_text` WHERE `entry` = 2597 AND `text_loc4` = '欢迎来到魔兽世界！年轻的战士，不要害怕这个陌生而充满神秘的提防，你会惊奇的发现许多潜伏在阴影中的危险，许多歹徒为了蝇头小利而准备杀了你……因为，提防身边的危险，随时做好战斗的准备，你才能好好地活着！';
DELETE FROM `locales_page_text` WHERE `entry` = 2598 AND `text_loc4` = '欢迎来到魔兽世界！年轻的士兵啊，你已经准备好了成为一名圣骑士了吗？很好……记住要勇敢，击败邪恶扞卫正义！最重要的是，要相信上帝，并且你是他的助手……';
DELETE FROM `locales_page_text` WHERE `entry` = 2599 AND `text_loc4` = '欢迎来到魔兽世界！你管自己叫做盗贼？别搞笑了，如果你想成为一名真正的盗贼，就让我看看你有什么能耐，现在就去抢劫这座村庄给我看看！';
DELETE FROM `locales_page_text` WHERE `entry` = 2600 AND `text_loc4` = '欢迎来到魔兽世界!孩子，如果你崇拜上帝，你将被救赎……如果你崇拜恶魔，你将获得力量，但却被上帝抛弃……所以，一定要当心，我的孩子，一定要当心！';
DELETE FROM `locales_page_text` WHERE `entry` = 2601 AND `text_loc4` = '欢迎来到魔兽世界!这个世界对我们萨满来说太险恶了，但是我们仍然足够强大来赢得这场圣战……我们先得采取些措施，杀死这些讨厌的联盟。现在让我看看，我们萨满到底有多厉害！';
DELETE FROM `locales_page_text` WHERE `entry` = 2602 AND `text_loc4` = '欢迎来到魔兽世界！我们法师是最强大的魔法使用者，我们将冰霜与火焰的力量发挥到极致，我们能够做任何想做的事！所以，来探索魔法的精髓吧！';
DELETE FROM `locales_page_text` WHERE `entry` = 2603 AND `text_loc4` = '欢迎来到魔兽世界！术士是一个神秘的群体……我们有最强大的魔法，忘了那些法师们吹嘘说他们的法术多么厉害云云，记住，我们术士是从法师发展而来的，所以实际上我们是更强大的！';
DELETE FROM `locales_page_text` WHERE `entry` = 2604 AND `text_loc4` = '欢迎来到魔兽世界！部落唤醒了你的力量，我的孩子……现在你已经成为一名善变的德鲁伊了。你集合了战士的力量、法师的智慧、萨满的精神……我们是独特的！你必须帮助你的朋友们，因为我们德鲁伊是支援力量的极致！';
DELETE FROM `locales_page_text` WHERE `entry` = 2610 AND `text_loc4` = '使用灵魂护符的力量来强迫他们显形，并从他们那里取得宝石!在此之後，把宝石放入灵魂护符之中，然後把它交给我。当我有了联合护符之後，我就有足够的力量来对我们的部族进行改革了，那样我们就能完成先祖的遗愿了!';
DELETE FROM `locales_page_text` WHERE `entry` = 2630 AND `text_loc4` = '……那就是你可以找到血色大领主之剑的地方，灰烬使者。$B$B是不是很惊讶?';
DELETE FROM `locales_page_text` WHERE `entry` = 2891 AND `text_loc4` = '纪念最高结盟指挥官，安杜因·洛萨:一个牺牲一切保护他的君王，他的人民，他的家园的人……$B$B让我们的敌人知道我们的名字。让我们的盟友光耀我们的逝者。我们是洛萨之子 。$B$B- 图拉扬将军';
DELETE FROM `locales_page_text` WHERE `entry` = 2892 AND `text_loc4` = '$B   这里躺着一个大胆的苦工遗体。他试着奋斗，但只是徒然。';
DELETE FROM `locales_page_text` WHERE `entry` = 2905 AND `text_loc4` = '这里有一个灰烬之罐。这些灰烬是我的精神，我的热情，和我的本能需要。全部，都被他们摧毁了。愿所有来到地狱火这凄凉土地的人都记得这死去的苦工。他为了联盟流血流汗，被部落逼的彻底发疯，因为那些邪恶，没有灵魂的人将他的最爱毁灭。他们因为他的苦力而享受，愿他们也因为他的愤怒而痛苦。或许不是在这个世界，而是在之後的每一个世界。这是我的宣言，我严肃的誓约，也是我永恒的承诺。我会为我的苦难报复。';
DELETE FROM `locales_page_text` WHERE `entry` = 2906 AND `text_loc4` = '审视小岛的范围并回报状况。$B$B记得，不要被抓到!$B$B不要让我失望，坎翠斯!$B$B火花。';
DELETE FROM `locales_page_text` WHERE `entry` = 2907 AND `text_loc4` = '草图显示沙德拉洛和它的三座神庙，有一些「x」记号的，都与被偷窃的蛋下落有关。记号出现在东边神庙的南方尽头，和东边神庙的东北边一间小茅屋很近，靠近中央湖东边的一个祭坛，在靠近「放逐」字样的南方神庙斜坡上。$B$B羽须的便笺暗示他正在计画传送消息给弗斯塔德·蛮锤，希望他能派遣一批战士去拯救那些蛋。';
DELETE FROM `locales_page_text` WHERE `entry` = 2909 AND `text_loc4` = '$B迪亚索鲁斯，$B$B我相信这封信最终一定会到你手上。这些恶魔真是没脑子的生物。他们脑袋里想的只有他们的爪子，鞭子，或是用他们的头钉刺穿什麽东西。我不敢使用任何一个炼狱火否则一切都会被烧成灰烬!$B$B可悲的是，我怀念那些奴役兽人的日子。至少他们有一半的脑袋还会听从命令。或许有机会从附近再找一些新的奴隶来?';
DELETE FROM `locales_page_text` WHERE `entry` = 2910 AND `text_loc4` = '$B有关夜精灵协助德莱尼的报告是真的。他们想在北边萨提纳尔附近的林歌神殿建立一个新的运作基地。我们应该协商一下，在这可悲的世界下一次月圆前联合我们的军队做一次攻击。如果我们现在制服他们，他们才会记得「部落」这个词真正的意义为何!$B$B戈甘诺恩$B$B致意$B$B备注 - 不要再用血墨水写情书给我的鞭笞者!夜精灵处女最近很短缺。';
DELETE FROM `locales_page_text` WHERE `entry` = 2911 AND `text_loc4` = '$B迪亚索鲁斯，$B$B我相信这封信最终一定会到你手上。这些恶魔真是没脑子的生物。他们脑袋里想的只有他们的爪子，鞭子，或是用他们的头钉刺穿什麽东西。我不敢使用任何一个炼狱火否则一切都会被烧成灰烬!$B$B可悲的是，我怀念那些奴役兽人的日子。至少他们有一半的脑袋还会听从命令。或许有机会从附近再找一些新的奴隶来?';
DELETE FROM `locales_page_text` WHERE `entry` = 2912 AND `text_loc4` = '$B是时候夺回一些次要种族了，我想。西北边的碎木岗哨是个很诱人的目标。我们应该协商一下，在这可悲的世界下一次月圆前联合我们的军队做一次攻击。如果我们现在制服他们，他们才会记得「部落」这个词真正的意义为何!$B$B戈甘诺恩$B$B致意$B$B备注 - 不要再用血墨水写情书给我的鞭笞者!夜精灵处女最近很短缺。';
DELETE FROM `locales_page_text` WHERE `entry` = 2913 AND `text_loc4` = '虽然几乎被击败$B他依旧充满了勇气$B拔剑出鞘$B向那些恶魔冲锋$B$B因为那些暴力的日子$B不要箭，也不要剑$B寻找，不在战斗中也不在冲突里，$B这是矮人领主的方法';
DELETE FROM `locales_page_text` WHERE `entry` = 2914 AND `text_loc4` = '……但她已经知道了。在她将自己的灵魂一点一滴的交换出去後，她已经认命的过着贱民的生活了。复仇已经值得了，或是她这样想。$B$B但现在有个机会让她重拾人性，所有的陌生人要交换的就是她的信任。$B$B「让我来」，卡崔恩说。「我没什麽好怕的。」';
DELETE FROM `locales_page_text` WHERE `entry` = 2916 AND `text_loc4` = '维斯路登，$B$B由於黑暗之门再次开启，荣誉堡和索尔玛都从艾泽拉斯接获了强大的援军。当我们还得准备应付燃烧军团的攻击时，报告指出他们正计画要攻击堡垒。这是无法令人接受的!$B$B我们不能让血熔炉的运作陷入危险之中!在那里制造出来的魔狱兽人就是我们成功的关键。加强堡垒的防御并立刻分派更多周边守卫!$B$B相信我，你不会想让我亲自去拜访你的。$B$B-伊利丹';
DELETE FROM `locales_page_text` WHERE `entry` = 2917 AND `text_loc4` = '维斯路登，$B$B由於黑暗之门再次开启，荣誉堡和索尔玛都从艾泽拉斯接获了强大的援军。当我们还得准备应付燃烧军团的攻击时，报告指出他们正计画要攻击堡垒。这是无法令人接受的!$B$B我们不能让血熔炉的运作陷入危险之中!在那里制造出来的魔狱兽人就是我们成功的关键。加强堡垒的防御并立刻分派更多周边守卫!$B$B相信我，你不会想让我亲自去拜访你的。$B$B-伊利丹';
DELETE FROM `locales_page_text` WHERE `entry` = 2918 AND `text_loc4` = '我做了这件事。我不记得我有做，但也没有别的可能了。$B$B我以前犯过罪。我甚至还杀过一个无辜的人。但这次不同。$B$B我改变了。$B$B这些谋杀不是我的选择。有一只野兽住在我心里。$B$B我会被追捕和回避。我要躲起来。逃跑。埋葬屍体。$B$B当我真正了解是什麽在困扰着我时，我开始到外面走动。$B$B我感觉不到罪恶。';
DELETE FROM `locales_page_text` WHERE `entry` = 2919 AND `text_loc4` = '仆人，$B$B值得计画的几年已经过去了。德莱尼和他们可悲的领导者又再次从主人的手里逃走了!更重要的是，他们偷走了我的飞船还让它在艾泽拉斯坠毁!$B$B虽然主人的埃雷达尔密探失败了，但她能将艾克索达的地点传送给我们。很幸运，她的身份对德莱尼而言仍是个谜，我们还是可以利用她来达到我们的目的。';
DELETE FROM `locales_page_text` WHERE `entry` = 2920 AND `text_loc4` = '联络我们的间谍并准备全面性突击德莱尼。杀光他们并取回我的飞船。你是艾泽拉斯上唯一可以修补那些畜生对艾克索达造成的损坏的人，又是我唯一的连系。$B$B不要让我失望，侏儒。如果你对财富的渴望干扰了我的命令，你来世就等着祷告吧。如果你失败了我会让你痛不欲生，你会祈求死亡快点到来将你从痛苦中释放。$B$B-逐日者之王';
DELETE FROM `locales_page_text` WHERE `entry` = 2923 AND `text_loc4` = '部落受人尊敬的领导者，$B$B我 - 洛索玛·塞隆，奎尔萨拉斯地区统治者 - 非常荣幸的宣布我们所知道的达克汗·崔希尔，天谴军团的指挥官阵亡了。$B$B达克汗在我们土地上的立足点是由辛多雷种族的评论家在先前无数次的协商中所建立的。我们希望这个事件能平抚所有你心里可能有的异议。$B$B<署名>洛索玛·塞隆';
DELETE FROM `locales_page_text` WHERE `entry` = 2924 AND `text_loc4` = '部落受人尊敬的领导者，$B$B我 - 洛索玛·塞隆，奎尔萨拉斯地区统治者 - 非常荣幸的宣布我们所知道的达克汗·崔希尔，天谴军团的指挥官阵亡了。$B$B达克汗在我们土地上的立足点是由辛多雷种族的评论家在先前无数次的协商中所建立的。我们希望这个事件能平抚所有你心里可能有的异议。$B$B<署名>洛索玛·塞隆';
DELETE FROM `locales_page_text` WHERE `entry` = 2925 AND `text_loc4` = '$B$B备注 - 我们的大师常收到外域捎来消息回覆索尔的问题。答案是，当然，是的。$B$B<这本书的薄薄书页是由一种微微发亮的材质做的，充满了高科技图表说明如何维护和修理超空间船舰。这份副本打开到一篇标题为「旋绕导航器损坏及如何避免」的章节。>';
DELETE FROM `locales_page_text` WHERE `entry` = 2926 AND `text_loc4` = '$B$B备注 - 我们的大师常收到外域捎来消息回覆索尔的问题。答案是，当然，是的。$B$B<这本书的薄薄书页是由一种微微发亮的材质做的，充满了高科技图表说明如何维护和修理超空间船舰。这份副本打开到一篇标题为「旋绕导航器损坏及如何避免」的章节。>';
DELETE FROM `locales_page_text` WHERE `entry` = 2930 AND `text_loc4` = '$N，$B$B血淬三叉矛的创造需要许多稀有又易变的材料，才能制作出最佳手工的可怕武器。我会将材料清单从最容易到最难取得的顺序排列。$B$B别忘了你也一定要在材料被接受前保护血骑士徽记，这样铸造的过程才会开始。';
DELETE FROM `locales_page_text` WHERE `entry` = 2931 AND `text_loc4` = '愤怒之血 - 为了恰当地锻链武器的金属，它一定要在愤怒之血里被冷却。虽然大部份恶魔的血液都有实质力量，但普通的血却不足以铸造你的三叉矛。$B$B谨慎询问奥格玛的术士之後对寻找鲜血的补给有了帮助。怒焰裂谷里的灼刃祭司拥有一种充满鲜血的宝珠，那就是我们要制造你武器所需的东西。我听说那颗宝珠由一个自称『塑能师』耶戈什的兽人守卫着。$B$B小心行动，所有和恶魔力量的往来都要注意。握有这样强大的物体时你永远也不知道会发生什麽事。';
DELETE FROM `locales_page_text` WHERE `entry` = 2932 AND `text_loc4` = '一箱血铸锭 - 只有一箱，钢铁是很好的金属，但由它铸造的武器则不值得注意。血铸锭代表一种极好的金属，而它的制作过程一直是个秘密。传说任何敢触碰并使用这个金属的铁匠都被诅咒了，但我们的工匠已证明这是个谬论。$B$B这个金属的名声增加了它的稀有度，但被遗忘者却声称在影牙城堡可能有补给。一个叫做蓝登·史帝威尔技艺高超的铁匠非常好奇，便走私了一箱血铸锭。没人知道他把东西藏在哪里，但我们的消息告诉我们那名铁匠现在被囚禁在城堡的地城里。用尽所有方法取得那箱血铸锭。';
DELETE FROM `locales_page_text` WHERE `entry` = 2933 AND `text_loc4` = '一颗被污染的科尔宝石 - 博学者的墓碑记载着这些宝石曾被一些施法者用来保留他们的魔法能量，让他们更致命。虽然纯净的宝石可以安全地被中级施法者使用，但它们对我们的目的而言仍嫌太弱。$B$B在黑涧深渊的洞穴中，纳迦施法者将科尔宝石注入他们自己的黑暗力量，增强它们的力量，以便在你的三叉矛中完美地被使用。在你弄到需要的宝石之前先无情的杀了他们。';
DELETE FROM `locales_page_text` WHERE `entry` = 2934 AND `text_loc4` = '你将戴上的徽记最後一次是被晨星家族中一个勇敢无惧的血骑士所配戴。他典范的奉献是你在骑士团生涯的好预兆。$B$B血骑士晨星对死亡之域的天谴军团要塞率领了一次大胆，但最终失败的攻击。他的屍体就在他死去的地方安息，与我们最强劲的敌手锁在战斗中。找到他，$N，并将他的徽记带来给我。你的成功会为他，为你，为所有真正的血骑士带来荣耀。';
DELETE FROM `locales_page_text` WHERE `entry` = 2936 AND `text_loc4` = '你发现了神殿的位置!进一步的检查之後，你感觉到一股更强大的陌生力量控制了岛屿。你觉得站在神殿旁有点不舒服……甚至有点心乱。$B$B神殿旁的青铜色公告牌上写着:$B$B「这是达斯雷玛神殿，对最高尚的精灵们致上最高的敬意。让所有景仰过这个纪念碑的人都会记得他对抗天谴军团的牺牲及对我们继续生存的事业贡献。所有让奎尔萨拉斯繁荣的人们也都感谢他。」';
DELETE FROM `locales_page_text` WHERE `entry` = 2937 AND `text_loc4` = '我看着他们无情的鞭打他。他们残酷的中尉一举一动就好像残暴是正常的事一样。经过野蛮的鞭打之後，我可以感觉我已经崩溃了。$B$B看着复仇者萨鲁安忍受他们的殴打，我开始哭泣。并不是因为害怕……而是因为悲伤。看到三头政治的德莱尼被这样对待。要是我能打破我的束缚就好了。要是可以的话……';
DELETE FROM `locales_page_text` WHERE `entry` = 2938 AND `text_loc4` = '在看起来像实体的东西出现後，复仇者就失去意识了。这实在太折磨了，即使是对他而言也一样。残忍的 - 马帝斯，据悉他是被这样称呼的 - 还将传染的水泼洒在萨鲁安毁坏的身上想叫醒他。但萨鲁安并没有醒来。';
DELETE FROM `locales_page_text` WHERE `entry` = 2939 AND `text_loc4` = '我想尖叫可是只有一声低喘迸出我嘴边。我很快就被这次的反叛行动给打败。当我躺在地上，我可以看见马帝斯在萨鲁安的屍体前跺步。他看起来很担心。他声称如果萨鲁安被後打死去，赛罗娜斯或赛罗娜或类似这样的实体会把他的肉体从骨头上剥下。';
DELETE FROM `locales_page_text` WHERE `entry` = 2940 AND `text_loc4` = '赛罗娜斯实体对萨鲁安有个计画……$B$B<书写突然中断，一条长长的线画过页面。这个德莱尼在制造实体时死去。>';
DELETE FROM `locales_page_text` WHERE `entry` = 2941 AND `text_loc4` = '莉雅德伦女士，$B$B最近被俘虏的生物制造了一些麻烦，让我们一些最重要的装备遭到损坏。恢复一切的工作让我的博学者和资源都大大的减少。我已将事件报告呈交给大博学者洛摩斯，但他回覆的速度很慢。我担心没有下列的物品我们会被迫缩减运作，而你知道那对你的骑士们而言代表着什麽。$B$B如果你可以有任何的帮助，我已在下一页列好了材料清单。我们会感谢你的军队所能提供的任何协助。$B$B博学者阿斯塔乐·血誓';
DELETE FROM `locales_page_text` WHERE `entry` = 2942 AND `text_loc4` = '*40块符文布$B*6条奥金锭$B*10根太阳草$B*5个黑暗符文$B*150金';
DELETE FROM `locales_page_text` WHERE `entry` = 2943 AND `text_loc4` = '太阳之王的宣言 - 我亲爱、忠诚的孩子们 - 你们的君王命令你们。你们来到艾泽拉斯对我和主人都具有很重要的意义。$B$B很快的，太阳之门就会准备好将风暴要塞的援军直接传送至血谜岛。$B$B我们会夺回艾克索达。我们会杀死蓝皮肤的杂种狗。费伦会为他的罪行付出代价。$B$B-凯尔萨斯·逐日者之王';
DELETE FROM `locales_page_text` WHERE `entry` = 2975 AND `text_loc4` = '蠢蛋，$B$B寻找食物。蓝色的味道不错。剑刃传授者说还可以。把食物带给浪普。浪普先吃然後蠢蛋再吃。可以吗?动作快点否则浪普就要吃你了。$B$B-浪普';
DELETE FROM `locales_page_text` WHERE `entry` = 2976 AND `text_loc4` = '(1)『酒鬼』拉利克:巨魔。他从未离开小酒店。很坏。很丑。很胖。很坏。又非常胖。$B$B[下一页]';
DELETE FROM `locales_page_text` WHERE `entry` = 2977 AND `text_loc4` = '(2)库库许:这个从赞格沼泽来的讨厌小孢子人在赞格沼泽和泰洛卡的边界有一个蘑菇园。在「那是什麽味道」的游戏中输了很多金子给沙萨拉毕恩。想用叫做空茎的白闪菇付给沙萨拉毕恩。说这跟黄金一样好!哈!$B$B[下一页]';
DELETE FROM `locales_page_text` WHERE `entry` = 2978 AND `text_loc4` = '(3)服伦:阿拉卡。输给沙萨拉毕恩许多金子。鸟人因为没有付钱就被沙萨拉毕恩杀死了。现在鬼魂鸟人在白骨荒野的西北方走着。';
DELETE FROM `locales_page_text` WHERE `entry` = 2979 AND `text_loc4` = '奥莱姆贝根茎是泰洛卡森林里一种普遍的根茎植物。到构成泰洛卡森林的奥莱姆贝树丛附近搜寻向上翻起的根茎。$B$B沼泽莓只生长在赞格沼泽。只能在安格拉斯要塞找到它，就在沼泽的西北区。小心那些守卫珍贵莓子的巨魔。$B$B泰拉蕊藻叶或许是这清单上最容易取得的草药。你可以在泰拉蕊盆地的卡拉达尔南方找到藻叶。它们生长在水边。$B$B清单上最後一种草药是剑刃山脉特有的植物。你可以在赞格沼泽北边找到剑刃山脉。龙脊生长在守卫着剑刃山脉峡谷的锯齿状岩石地形尽头。等你见到了剑刃山脉就会知道我在说什麽了。那个岩石地形就像是一排排的尖锐牙齿。';
DELETE FROM `locales_page_text` WHERE `entry` = 2981 AND `text_loc4` = '我的仆人，这些兽人正遇上一个小小的麻烦，我想要你亲自去搞定它，我们的部队正在进攻黑暗之门的守卫，他们的精力都被浪费在了萨尔玛。这是命令！——阿拉修斯';
DELETE FROM `locales_page_text` WHERE `entry` = 2982 AND `text_loc4` = '我的仆人，这些兽人正遇上一个小小的麻烦，我想要你亲自去搞定它，我们的部队正在进攻黑暗之门的守卫，他们的精力都被浪费在了萨尔玛。这是命令！——阿拉修斯';
DELETE FROM `locales_page_text` WHERE `entry` = 2983 AND `text_loc4` = '要让饮用者看见彩色幻象的亡灵，就一定要收集到一些特定的材料。$B$B首先，西纳葛兰的山地古罗眼球，靠近燃烧军团被诅咒的炼冶场，战槌山丘南方。$B$B在西纳葛兰也可以找到巨型风翼猫头鹰。只有完美的品种才行!$B$B最後，在纳葛兰西边和西南边有老迈的裂蹄油。$B$B收集这些物品再回来找我!动作快!$B$B-奈崔恩';
DELETE FROM `locales_page_text` WHERE `entry` = 2984 AND `text_loc4` = '<在好几页令人伤透脑筋看似毫无道理的\'科学\'之後，最後一页的底端是一则草写的笔记……>$B$B抱歉，老板。看来虚空风暴很快就要爆炸了。或许外域所剩之地的大部分都会遭殃。$B$B我不是百分之百确定，但我认为问题就出在那些法力熔铁炉里的血精灵身上。$B$B你建造那枚火箭是好事!$B$B-卡伯尼寇斯$B$B注. - 你可以帮我在火箭上弄个位子吗?在你巡航於扭曲虚空时绝对需要一个地狱学家!';
DELETE FROM `locales_page_text` WHERE `entry` = 2985 AND `text_loc4` = '将军，$B$B我们正守住命运阶梯的战线，但军团派出了一波又一波的人马来攻击我们军队。他们在附近一定有个集结地是我们斥候尚未找到的。虽然这里的联盟军队是站在我们的阵线，我担心军团的众多数量会超出我们的防御。尽量伸出你的援手，否则传送门瘫痪 - 我们就要永远被困在这个梦魇世界了。$B$B欧莱恩中将';
DELETE FROM `locales_page_text` WHERE `entry` = 2986 AND `text_loc4` = '当纳尼滑上来时，这位沧桑的战士给了她一个严厉的眼神。「我想你待在这里是为了蒐集杀死鱼人的奖励吧?」$B$B她的眼神移到了他身边闪亮的宽剑。「马库斯，这要看奖励是什麽。」她玩弄着她的头发，假装没有注意到他对她的存在感到不自在。「我可能并不想要这个奖励。」';
DELETE FROM `locales_page_text` WHERE `entry` = 2987 AND `text_loc4` = '马库斯走向她，恐惧与愤怒的情绪交织地站着。「这个奖励是没得商量的!」他稍微停顿，整理一下紧张的心情，然後逼近她娇小的身躯。他们的双唇火热地交缠着，激情的气息满溢，融化了她的冰霜护甲法术。$B$B「所以，这个任务有下一个步骤吗?」她的双眼闪着兴奋的光芒，挑逗着他。$B$B<这样的情节持续了数百页，完全没有任何进一步的剧情。>';
DELETE FROM `locales_page_text` WHERE `entry` = 2988 AND `text_loc4` = '虽然这个奇特的物品完全不像你过去见过的任何东西，但是它很像是某种工程装置。$B$B从外观看来，不管这是什麽，都已经被使用过了。$B$B依照附近四散的屍体来看，你猜不管这个装置是什麽，效果都是致命的。';
DELETE FROM `locales_page_text` WHERE `entry` = 2989 AND `text_loc4` = '指挥官，$B$B这个密码要被送到祖鲁希德那里。在进一步的通知之前，这个物品必须在他的保管之下。$B$B-伊利丹·怒风';
DELETE FROM `locales_page_text` WHERE `entry` = 2990 AND `text_loc4` = '<HTML><BODY><BR/><H1 align="center">精灵贵族的挽歌</H1><BR/><IMG src="Interface\\FlavorImages\\BloodElfLogo-small"/></BODY></HTML>';
DELETE FROM `locales_page_text` WHERE `entry` = 2991 AND `text_loc4` = '<HTML><BODY><P>简译版……';
DELETE FROM `locales_page_text` WHERE `entry` = 2992 AND `text_loc4` = '<HTML><BODY><P>萨拉斯版……';
DELETE FROM `locales_page_text` WHERE `entry` = 2993 AND `text_loc4` = '亲爱的大法官，$B$B把暗影之月的巨人们带到峡谷的任务现在已经落在了你的肩上，运用你血精灵的魅力，使他们用我的方式看事情。如果你无法做到这一点，就把他们杀得鸡犬不留……$B$B伊利丹·怒风';
DELETE FROM `locales_page_text` WHERE `entry` = 2994 AND `text_loc4` = '无论如何，圣骑士的行为必须与圣光对应，圣光是我们力量的来源。我们其中的一员为了神而奋战，并不代表我们为了神性而奋战，我们一切的行动都是为了努力追求至善。';
DELETE FROM `locales_page_text` WHERE `entry` = 2995 AND `text_loc4` = '就算在这个艰困的时局中被号召前来打击邪恶，你必须永远记住，帮助别人才会真正地让你与众不同。同情心，耐心与勇气就是圣骑士作战时的最大力量。$B$B清楚地了解这个道理，永远也不要忘记。';
DELETE FROM `locales_page_text` WHERE `entry` = 2996 AND `text_loc4` = '责任免除切结书。$B$B测试飞行员已充分的了解并同意此测试行为有可能在使用ZC号(以下称为「此装置」)时因为机体粉碎、电击、钝器撞击要害、动植物引起疾病、时间/空间错乱而造成受伤、肢解或者死亡。测试飞行员於此切结自愿进入此装置并且承担所有以上的风险。$B$B测试飞行员同意放弃、转让并且免除对塔利·萨普纳伯和其家人所有的索赔权利，并且一旦发生死亡意外时，$G他:她;同意将遗体捐赠给萨普纳伯机构做进一步的研究。$B$B署名，$BX:___$N';
DELETE FROM `locales_page_text` WHERE `entry` = 2997 AND `text_loc4` = '您好，学有所成的安拓维奇:$B$B我希望你能在索尔玛收到这封信，并且对你的研究有所帮助。虽然我还是希望能回到幽暗城，因为那边有全面性的工具与仆人可以协助我，但是我在断脊氏族的关系已经足以应付我的实验。$B$B啊，死者的挽歌。$B$B先聊到这，我有一些有趣的消息---$N从魔狱兽人身体上采集的血液出现了恶魔腐化的浓缩体。这几乎与原来艾泽拉斯上受到恶魔腐化的魔狱兽人完全相同……玛诺洛斯的腐化之血。';
DELETE FROM `locales_page_text` WHERE `entry` = 2998 AND `text_loc4` = '$N,$B$B毁灭密码的确是一个很强大的法术，古老而且混乱，密码本身必须对我们这个世界所发生的许多历史悲剧负责。这也就是说，对於德拉诺来说这并不是单一事件。$B$B你看到的燃烧象徵是凯尔萨斯的徽记。他对古代文字的知识解释了许多事情。$B$B你的发现已经使那鲁觉醒。阿达欧也邀请你来撒塔斯城。如果你要过来的话，可以在圣光露台找到我。$B$B您谦卑的，$B$B卡德加';
DELETE FROM `locales_page_text` WHERE `entry` = 2999 AND `text_loc4` = '安拓维奇，$B$B首先，让我们来说说你上一个派来的人，$N，$G他:她;在工作上的表现已经远超过我的预期了。我已经占据了$G他:她;的身体，并且用$G他:她;的手来写这封信。这对我来说是多大的享受啊，我希望有一天我能有幸占据你的身体，强大的药剂师!$B$B所以，你要求我所做的报告如下:在地狱火堡垒内肆虐的恶魔比我过去遭遇过的强大许多。我猜想在第三次战争时着名的深渊领主玛诺洛斯就掌握了同样的力量，但拥有这股力量的生物屈指可数。然而，我感觉到有一股禁锢之风围绕着这个恶魔。如果它做出了违背其意愿的事情，我一点都不会感到惊讶，也许他是被囚禁或是在更强大的力量控制之下。$B$B时间会说明一切的………';
DELETE FROM `locales_page_text` WHERE `entry` = 3000 AND `text_loc4` = '在地狱火堡垒的高墙内，我也感觉到命运的移转，就像他们说的一样，时间会证明一切。$B$B你将会在此见识到恶魔的面容，来自艾泽拉斯的外来者，那里的繁茂生机，对於我来说就像是充满圣光与生命的地狱。如果你能允许我用比喻的话，你会明白在地狱火堡垒中的邪恶生物，只不过是巨大冰山的一角。$B$B喔，在我面前的是一场多麽荣耀的战斗啊!也许只有我可以品尝到即将被执行的痛苦与恐怖!$B$B呃，我应该结束我们之间乏味的对话，并且让你慢慢想清楚以下的文字，亲爱的药剂师:你的身体可能是死的，安拓维奇，但是你的灵魂仍然十分完整，在你的防守发生失误，并且让我有机会接近你的那天，我应该啃食你的灵魂，并且在极佳的开胃菜搭配下，尽情的享用!如果必须的话，我会等到审判的第四天，但是，你会是我的!$B$B晚安,$B-D';
DELETE FROM `locales_page_text` WHERE `entry` = 3001 AND `text_loc4` = '<在这张严重烧毁的页面上已经没有任何可以辨识的字迹了。>';
DELETE FROM `locales_page_text` WHERE `entry` = 3002 AND `text_loc4` = '自从你离开永恒树林後，我继续进行乌鸦圣典的研究，并发现一些有助於你打败乌鸦神的资讯。$B$B解放这些灵魂已经将他们跟你绑束在一起，因此我认为他们可以自由的在对抗乌鸦神的战斗中提供他们的协助。$B$B当你第一次解放灵魂时，他们将会处於休眠状态，因为他们几世纪以来都是如此。使用你的持续性疗癒法术，你可以以能量灌注他们，给予他们生命并在战斗中得到他们的协助。当魔法消退，他们将回复休眠状态。$B$B接下来就是一系列我对每个鸟灵的注记:';
DELETE FROM `locales_page_text` WHERE `entry` = 3003 AND `text_loc4` = '猎隼灵魂$B$B猎隼灵魂充满了惊人的速度跟敏捷，在阿拉卡所关注的猎人技术当中受到高度的重视。如果你以持续性疗癒法术给予灵魂能量，它将赋予你於法术施放及近身战斗方面有一定程度的速度。';
DELETE FROM `locales_page_text` WHERE `entry` = 3004 AND `text_loc4` = '战鹰灵魂$B$B阿拉卡传统将战鹰灵魂配置得不似它的猎隼兄弟一样迅速，不过它所掌管却是狩猎中最高超的技术。如果你使用持续性疗癒法术使他从休眠中苏醒，战鹰灵魂将会使用它的技术来对抗你的敌人。$B$B。';
DELETE FROM `locales_page_text` WHERE `entry` = 3005 AND `text_loc4` = '猎鹰灵魂$B$B石板上谈到很多有关猎鹰的事，好像他曾经是乌鸦的盟友。一个远古阿拉卡的复仇符号，猎鹰灵魂常常被罪恶的受害者召唤。使用持续性疗癒法术来唤醒这个灵魂将会使你能够分享它的力量，毁坏那些伤害你的人。';
DELETE FROM `locales_page_text` WHERE `entry` = 3006 AND `text_loc4` = '以我们伟大主人的名义……为了伊利丹的荣耀!$B$B莫格，$B$B我把这个软弱的可怜虫送给你做为伊利丹的仆人。虽然他无法成为一名死亡骑士，你还是会发现他有一些适合你喜好的技能。把他打到屈服为止。让他成为伊利达瑞的战士。$B$B如果他失败……如果他展现出脆弱……就把他丢弃，把他丢进深渊!$B$B泰朗·血魔领主';
DELETE FROM `locales_page_text` WHERE `entry` = 3007 AND `text_loc4` = '不要绝望。你的特殊巨魔就在那里的某个地方。';
