DELETE FROM `locales_page_text` WHERE `entry` = 3024 AND `text_loc4` = '抱歉，这次你不是赢家。请再玩一次。';
DELETE FROM `locales_page_text` WHERE `entry` = 3025 AND `text_loc4` = '你今天会树敌，并立刻杀了它。';
DELETE FROM `locales_page_text` WHERE `entry` = 3027 AND `text_loc4` = '寻找生命中更崇高的一条道路。在那条路上，你可以避开一些鄙恶之人。';
DELETE FROM `locales_page_text` WHERE `entry` = 3028 AND `text_loc4` = '以我们伟大主人的名义……为了伊利丹的荣耀!$B$B灵魂火炮的常见原料可以在不同的商人那里取得。工程师和矿工可以提供你魔钢锭，克银能量核心和坚钢骨架。$B$B而完美的秘法精华则一定要到泰洛卡森林取得。在森林中心，部落前哨碎石堡的上方，你会找到萨希斯的家，他是一个阿拉卡异教徒。那个地方叫佐鲁湖。$B$B和萨希斯谈谈并告诉他你要找的东西。记得说是我派你去的因为他欠我一、两个人情。$B$B照着萨希斯的话做你就会得到精华了。$B$B-巴萨斯';
DELETE FROM `locales_page_text` WHERE `entry` = 3029 AND `text_loc4` = '当我上一次在大厅里，鹰王伊奇斯身上带着泰洛克羽毛，做为他掌权的象徵。他应该还带着它来说服他的追随者他是泰洛克复活。$B$B我的兄弟，暗法师希斯在进行塞司克仪式时会戴着泰洛克面罩。$B$B至於泰洛克的传说，它被保管在鹰王伊奇斯房间外的一个拱形房间里，在符文法阵里面。';
DELETE FROM `locales_page_text` WHERE `entry` = 3030 AND `text_loc4` = '要让玛诺洛斯的影响力到达外域是不可能的 - 那只野兽已经死去多年 - 但我担心另一个深渊领主或许正控制那里。一个玛诺洛斯深渊领主的力量……可以腐败当地的兽人。$B$B我会继续对血之谷鲜血的研究，但我鼓励你去追查蛛丝马迹。还有，我担心，那个踪迹会通向地狱火堡垒深处。$B$B学者，$B药剂师艾柏瑞克';
DELETE FROM `locales_page_text` WHERE `entry` = 3031 AND `text_loc4` = '听着，霸德!$B$B这是最後一个我送去给你的傻瓜，除非你把欠债付清。$B$B不准再拖延了!$B$B格利夫塔';
DELETE FROM `locales_page_text` WHERE `entry` = 3032 AND `text_loc4` = '加尔恩，$B$B我应该不需要提醒你，你的任务有多重要 -- 不计代价保护你珍贵的货物。如我所承诺过，成功与谨慎将会获得财富的回报。$B$B别对你的「夥伴」饶舌，看紧那些船员，那一切都会很顺利。我等着你成功的消息。';
DELETE FROM `locales_page_text` WHERE `entry` = 3033 AND `text_loc4` = '我送去了一批可观的武力给你，长老，但你一定要小心注意你的活动。你的首要目标就是终止联盟对我们土地的扩张。某些为数不少的人类已经开始在贫瘠之地的边境上构筑一个巨大建筑物。$B$B一定要让他们知道自己在可悲的塞拉摩边界之外并不受欢迎。最後，告诫你一句话，长老:别让你的计画给蕨墙村的那些巨魔知道。那些野蛮的东西连最低程度的谨慎都办不到。$B$B - 亚加席姆';
DELETE FROM `locales_page_text` WHERE `entry` = 3034 AND `text_loc4` = '我这辈子亲眼看过最可怕的生物就是泰瑟尔。我只看过那个怪物一次，我想我是真的够幸运才能活下来!$B$B那是个黑暗而且风暴肆虐的夜晚。大海翻腾，暴雨交加，塞拉摩灯塔的光线几乎看不见。我们尽力地往灯塔前进，突然间，那只恶兽就从波涛间冲向我们的船只!';
DELETE FROM `locales_page_text` WHERE `entry` = 3035 AND `text_loc4` = '这个强大的生物张开血盆大口，向我们的船吐出冰弹，可怕的爪子抓住船弦，把船往山上撞击，水手和货物都被震到了海里，船也被撞成碎片，$B$B我能记得的最后一件事就是从断裂的船体里飞出来，掉到了海水中，被海浪淹没，世界变成漆黑一片，我想我就这么玩完了。当我醒来的时候，我正躺在塞拉摩的医务室里，我知道得有人把我们的经历讲出来。$B$B';
DELETE FROM `locales_page_text` WHERE `entry` = 3037 AND `text_loc4` = '小孩:乔艾与吉娜。妻子:苏珊娜';
DELETE FROM `locales_page_text` WHERE `entry` = 3039 AND `text_loc4` = '不要在我的坟茔上落泪。$B我不在那里，我也不入土长眠。$B$B我伴着群风飞舞狂啸，$B拂过北裂境的晶白霜雪。$B$B我是和煦的细雨，$B落在西部荒野的金黄麦田上。$B$B我是清晨的静默，$B漾在荆棘谷的丛林与绿蔓间。$B$B我在壮盛喧天的战鼓声中，$B伴着雷鸣般的蹄踏横跨纳葛兰。$B$B我是闪着温暖微光的繁星，$B散落在达纳苏斯的柔软梦境。$B$B我在鸣禽的宛啭之间，$B我在一切的美好之中。$B$B不要在我的坟茔上落泪，$B我不在那里。我也没有死去。';
DELETE FROM `locales_page_text` WHERE `entry` = 3044 AND `text_loc4` = '第一班，第七钟$B又一次在兰姆酒柜找到赛卓克。 惩处。';
DELETE FROM `locales_page_text` WHERE `entry` = 3065 AND `text_loc4` = '元素领主的忠诚仆人，就是此时此刻。$B$B我们在黑暗中受苦太久了，等候着我们的时刻，服务我们的主人，追寻着终将来临的末日。现在，虽然拉格纳罗斯姑息的火焰燃亮了整个夜空，我们现在握有了利器，能大洪水掀起战争与混乱!$B$B炎魔如今被禁锢在我们的世界。他无法施展他全部的力量，但依旧令人畏惧。将和它同样令人畏惧的敌手带到这个世界来，他们的冲突将会掀起一场元素大战，带来我们所期待的末日。';
DELETE FROM `locales_page_text` WHERE `entry` = 3066 AND `text_loc4` = '奈普图隆的部下中，有个名叫艾胡恩的强大冰霜领主。至今他仍在聚集力量要对拉格纳罗斯掀起战争。他只需要一个通道来进入我们的世界；一个由我们提供的通道。我们有盟友，有地点。我们也有力量与意志。$B$B和我们忠诚的新盟友与客人之间的最後协商，将会在一个安全遥远的地方，在我们梣谷原始据点的西北边。$B$B在这个无知的「节庆」结束前，艾胡恩将会在黑石山的深处面对拉格纳罗斯。这个世界将会因为他们释放出来的力量而倾覆。$B$B我们一切的努力都是为了这一刻。我们的主人将会再次兴起，彼此征战，并且将艾泽拉斯撕裂成碎片。$B$B我们将会活在时间的终结，我的兄弟。肩负起你的任务。努力下去。我们终将获胜!';
DELETE FROM `locales_page_text` WHERE `entry` = 3072 AND `text_loc4` = '我们一切的努力都是为了这一刻。我们的主人将会再次兴起，彼此征战，并且将艾泽拉斯撕裂成碎片。$B$B我们将会活在时间的终结，我的兄弟。肩负起你的任务。努力下去。我们终将获胜!';
